// Validate Template Selector output
const input = $input.first().json;
let output = input.output || input.response || input.text || input.content || '';

let parsed;
try {
  const mdMatch = output.match(/```json\n([\s\S]*?)\n```/) || output.match(/```\n([\s\S]*?)\n```/);
  if (mdMatch && mdMatch[1]) parsed = JSON.parse(mdMatch[1].trim());
  else {
    const jsonMatch = output.match(/\{[\s\S]*\}/);
    if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
    else parsed = JSON.parse(output);
  }
} catch (e) {
  return [{
    json: {
      valid: false,
      error: 'Parse error: ' + e.message,
      raw_output: output.substring(0, 2000),
      selected_template: 'Requirements Specification (SRS)',
      template_type: 'requirements',
      sections: ['Introduction', 'System Features', 'Non-Functional Requirements', 'Appendix'],
      rationale: 'Fallback due to parse error',
      skipped_sections: [],
      custom_sections: []
    }
  }];
}

if (!parsed.selected_template) parsed.selected_template = 'Requirements Specification (SRS)';
if (!parsed.template_type) parsed.template_type = 'requirements';
if (!Array.isArray(parsed.sections)) parsed.sections = ['Introduction', 'System Features'];
if (!Array.isArray(parsed.skipped_sections)) parsed.skipped_sections = [];
if (!Array.isArray(parsed.custom_sections)) parsed.custom_sections = [];
if (!parsed.rationale) parsed.rationale = 'No rationale provided';

return [{ json: { valid: true, ...parsed } }];
